&=e^x\int_0^x\sqrt{u}\,e^{-u}\,\mathrm{d}u.
\end{aligned}
$$
由于 $e^x\to1$，原极限等于
$$
\lim_{x\to0^+}
\frac{\displaystyle\int_0^x\sqrt{u}\,e^{-u}\,\mathrm{d}u}
{x^{3/2}}.
$$
分子、分母均趋于 $0$，使用洛必达法则：
$$
\begin{aligned}
\lim_{x\to0^+}
\frac{\displaystyle\int_0^x\sqrt{u}\,e^{-u}\,\mathrm{d}u}
{x^{3/2}}
&=
\lim_{x\to0^+}
\frac{\sqrt{x}\,e^{-x}}{\dfrac32\sqrt{x}}\\
&=\frac23.
\end{aligned}
$$

