n\ln\left(1+\frac1{n(1-2a)}\right).
\end{aligned}
$$
因为 $a\ne\dfrac12$，且当 $u\to0$ 时 $\ln(1+u)\sim u$，所以
$$
\lim_{n\to\infty}
n\ln\left(1+\frac1{n(1-2a)}\right)
=\frac1{1-2a}.
$$
